"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useGSAP } from "@gsap/react";
import DashboardOverlay from "@/components/DashboardOverlay";

if (typeof window !== "undefined") {
  gsap.registerPlugin(ScrollTrigger, useGSAP);
}

// Helper component to handle script loading for Visme
const VismeEmbed = ({ url, formId, title }: { url: string; formId: string; title: string }) => {
  useEffect(() => {
    const existingScript = document.querySelector('script[src*="vismeforms-embed.js"]');
    if (existingScript) existingScript.remove();

    const script = document.createElement('script');
    script.src = 'https://static-bundles.visme.co/forms/vismeforms-embed.js';
    script.async = true;
    document.body.appendChild(script);

    return () => {
      if (script.parentNode) script.parentNode.removeChild(script);
    };
  }, [url, formId]);

  return (
    <div 
      className="visme_d" 
      data-title={title} 
      data-url={`${url}?fullPage=true`} 
      data-domain="forms" 
      data-full-page="true" 
      data-min-height="100vh" 
      data-form-id={formId}
    />
  );
};

const FRAME_COUNT = 179;

export default function ScrollCanvas() {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  
  const [imagesLoading, setImagesLoading] = useState(true);
  const [loadProgress, setLoadProgress] = useState(0);
  const [mgmtModalOpen, setMgmtModalOpen] = useState(false);
  const [techModalOpen, setTechModalOpen] = useState(false);
  
  const imagesRef = useRef<HTMLImageElement[]>([]);
  
  // Element Refs for Text Animation
  const beatARef = useRef<HTMLDivElement>(null);
  const beatBRef = useRef<HTMLDivElement>(null);
  const sign1Ref = useRef<HTMLDivElement>(null);
  const sign2Ref = useRef<HTMLDivElement>(null);
  const sign3Ref = useRef<HTMLDivElement>(null);
  const sign4Ref = useRef<HTMLDivElement>(null);
  const indicatorRef = useRef<HTMLDivElement>(null);

  const loadImages = useCallback(async () => {
    let loaded = 0;
    const STEP = 2;
    const totalToLoad = Math.ceil(FRAME_COUNT / STEP);
    const loadPromises = Array.from({ length: totalToLoad }).map((_, idx) => {
      const i = idx * STEP;
      return new Promise<HTMLImageElement>((resolve) => {
        const img = new Image();
        img.onload = () => {
          loaded++;
          setLoadProgress(Math.floor((loaded / totalToLoad) * 100));
          imagesRef.current[i] = img;
          resolve(img);
        };
        img.onerror = () => {
          console.error(`Failed to load frame ${i}`);
          loaded++;
          setLoadProgress(Math.floor((loaded / totalToLoad) * 100));
          resolve(img); // Resolve anyway so it doesn't hang
        };
        img.src = `/sequence/ezgif-frame-${String(i + 2).padStart(3, '0')}.png`;
      });
    });

    await Promise.all(loadPromises);
    setImagesLoading(false);
  }, []);

  const drawFrame = useCallback((index: number) => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    const STEP = 2;
    const targetIndex = Math.floor(index / STEP) * STEP;
    const img = imagesRef.current[targetIndex];

    if (!canvas || !ctx || !img) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#050505";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    
    // Cover logic
    const ctxRatio = canvas.width / canvas.height;
    const imgRatio = img.width / img.height;
    
    let drawWidth, drawHeight;
    let offsetX = 0, offsetY = 0;

    if (imgRatio > ctxRatio) {
      drawHeight = canvas.height;
      drawWidth = canvas.height * imgRatio;
      offsetX = (canvas.width - drawWidth) / 2;
    } else {
      drawWidth = canvas.width;
      drawHeight = canvas.width / imgRatio;
      offsetY = (canvas.height - drawHeight) / 2;
    }

    ctx.drawImage(img, offsetX, offsetY, drawWidth, drawHeight);
  }, []);

  useEffect(() => {
    imagesRef.current = new Array(FRAME_COUNT);
    // eslint-disable-next-line react-hooks/set-state-in-effect
    loadImages().then(() => drawFrame(0));
    return () => { imagesRef.current = []; };
  }, [loadImages, drawFrame]);

  useEffect(() => {
    const handleResize = () => {
      if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
      }
    };
    window.addEventListener("resize", handleResize);
    handleResize(); 
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  // Use GSAP to synchronize timeline accurately over scroll
  useGSAP(() => {
    if (imagesLoading) return;

    // Headless proxy object to bind 0-119 value
    const playhead = { frame: 0 };

    const tl = gsap.timeline({
      scrollTrigger: {
        trigger: containerRef.current,
        start: "top top",
        end: "bottom bottom",
        scrub: 1, // Smooth dampening matching our previous 100 stiffness
      }
    });

    // Animate Frames
    tl.to(playhead, {
      frame: FRAME_COUNT - 1,
      snap: "frame",
      ease: "none",
      duration: 1, // The entire timeline acts as 1 full unit of "progress"
      onUpdate: () => drawFrame(playhead.frame)
    }, 0);

    // Scroll Indicator Hide (0 -> 10%)
    tl.to(indicatorRef.current, { opacity: 0, duration: 0.1, ease: "none" }, 0);

    // Beat A (0-20%) -> Fade in 0-5%, Holds 5-15%, Fades out 15-20%
    tl.fromTo(beatARef.current, { opacity: 0, y: 20 }, { opacity: 1, y: 0, duration: 0.05, ease: "power1.out" }, 0);
    tl.to(beatARef.current, { opacity: 0, y: -20, duration: 0.05, ease: "power1.inOut" }, 0.15);

    // Beat B (Dashboard on Left Side, visible initially, fades out on scroll)
    tl.to(beatBRef.current, { opacity: 0, x: -20, duration: 0.05, ease: "power1.inOut" }, 0);

    // Sign 1 (Management - Left) 15-30%
    tl.fromTo(sign1Ref.current, { opacity: 0, y: 30 }, { opacity: 1, y: 0, duration: 0.03, ease: "power2.out" }, 0.15);
    tl.to(sign1Ref.current, { opacity: 0, y: -30, duration: 0.03, ease: "power2.in" }, 0.30);

    // Sign 2 (Marketing - Right) 35-50%
    tl.fromTo(sign2Ref.current, { opacity: 0, y: 30 }, { opacity: 1, y: 0, duration: 0.03, ease: "power2.out" }, 0.35);
    tl.to(sign2Ref.current, { opacity: 0, y: -30, duration: 0.03, ease: "power2.in" }, 0.50);

    // Sign 3 (Technical - Left) 55-70%
    tl.fromTo(sign3Ref.current, { opacity: 0, y: 30 }, { opacity: 1, y: 0, duration: 0.03, ease: "power2.out" }, 0.55);
    tl.to(sign3Ref.current, { opacity: 0, y: -30, duration: 0.03, ease: "power2.in" }, 0.70);

    // Sign 4 (Financial - Right) 75-90%
    tl.fromTo(sign4Ref.current, { opacity: 0, y: 30 }, { opacity: 1, y: 0, duration: 0.03, ease: "power2.out" }, 0.75);
    tl.to(sign4Ref.current, { opacity: 0, y: -30, duration: 0.03, ease: "power2.in" }, 0.90);


  }, { dependencies: [imagesLoading, drawFrame], scope: containerRef });

  return (
    <div ref={containerRef} className="relative h-[1600vh] bg-[#050505]">
      {imagesLoading && (
        <div className="fixed inset-0 z-50 flex flex-col items-center justify-center bg-[#050505]">
          <div className="text-white/60 text-sm uppercase tracking-widest mb-4 font-medium">Loading Experience</div>
          <div className="w-48 h-1 bg-white/10 rounded-full overflow-hidden">
            <div 
              className="h-full bg-white transition-all duration-300 ease-out" 
              style={{ width: `${loadProgress}%` }}
            />
          </div>
        </div>
      )}
      
      <div className="sticky top-0 h-screen w-full overflow-hidden flex items-center justify-center pointer-events-none">
        <canvas
          ref={canvasRef}
          className="w-full h-full"
        />
        
        {/* Scroll Indicator */}
        <div 
          ref={indicatorRef}
          className="absolute bottom-12 left-1/2 -translate-x-1/2 flex flex-col items-center"
        >
          <div className="text-white/40 text-[10px] uppercase tracking-[0.2em] mb-3 font-medium">Scroll to Explore</div>
          <div className="w-[1px] h-12 bg-gradient-to-b from-white/40 to-transparent animate-pulse" />
        </div>
      </div>

      <div className="absolute inset-0 pointer-events-none">
        <div className="sticky top-0 h-screen w-full">
          {/* Beat A */}
          <div 
            ref={beatARef}
            className="absolute inset-0 flex items-center justify-center text-center px-4 opacity-0"
          >
            <div className="max-w-4xl">
              <h1 className="text-5xl md:text-7xl lg:text-8xl font-semibold tracking-tighter text-white/90 drop-shadow-lg mb-6">
                ENTRAIOT SOLUTION
              </h1>
              <p className="text-xl md:text-2xl text-white/60 font-light tracking-tight">
                Empowering innovation through AI, IoT, and intelligent solutions — that’s EntraIoT.
              </p>
            </div>
          </div>

          <div 
            ref={beatBRef}
            className="absolute left-[5vw] top-1/2 -translate-y-1/2 opacity-100 pointer-events-auto z-[60]"
          >
            <DashboardOverlay 
              onOpenMgmt={() => setMgmtModalOpen(true)} 
              onOpenTech={() => setTechModalOpen(true)} 
            />
          </div>
          {/* Sign 1: Management (Left) */}
          <div ref={sign1Ref} className="absolute inset-0 flex items-center justify-start w-full px-8 md:px-32 opacity-0 pointer-events-none">
  <a 
    href="#"
    onClick={(e) => {
      e.preventDefault();
      setMgmtModalOpen(true);
    }}
    className="max-w-[420px] w-full min-h-[500px] bg-[#111111]/95 backdrop-blur-md border border-white/10 rounded-2xl p-10 shadow-2xl pointer-events-auto cursor-pointer flex flex-col transition-transform duration-300 hover:-translate-y-2 text-left group"
  >
    <div className="flex-1">
      <h3 className="text-4xl font-light text-white mb-4 tracking-wide group-hover:text-blue-400 transition-colors">
        Management Workspace
      </h3>
      <div className="w-16 h-[2px] bg-blue-500/50 mb-6" />
      <p className="text-gray-400 text-base leading-relaxed font-light mb-8">
        Strategic oversight, executive communications, and organizational leadership.
      </p>
      
      <div className="flex justify-center w-full mb-8"><img src="/image/management.webp" alt="Management Workspace" className="max-h-[160px] object-contain opacity-90 drop-shadow-lg" /></div>
    </div>
    
    <div className="mt-auto pt-6 border-t border-white/10">
      <div className="bg-white/5 hover:bg-white/10 text-white px-6 py-4 rounded text-sm font-medium tracking-wide flex justify-between items-center transition-colors">
        <span>Enter Workspace</span>
        <span>→</span>
      </div>
    </div>
  </a>
</div>

          {/* Sign 2: Marketing (Right) */}
          <div ref={sign2Ref} className="absolute inset-0 flex items-center justify-end w-full px-8 md:px-32 opacity-0 pointer-events-none">
  <a 
    href="#"
    onClick={(e) => {
      e.preventDefault();
      window.dispatchEvent(new CustomEvent("open-department-login", { detail: { departmentName: "Marketing", targetUrl: "/marketing" } }));
    }}
    className="max-w-[420px] w-full min-h-[500px] bg-[#111111]/95 backdrop-blur-md border border-white/10 rounded-2xl p-10 shadow-2xl pointer-events-auto cursor-pointer flex flex-col transition-transform duration-300 hover:-translate-y-2 text-left group"
  >
    <div className="flex-1">
      <h3 className="text-4xl font-light text-white mb-4 tracking-wide group-hover:text-blue-400 transition-colors">
        Marketing Workspace
      </h3>
      <div className="w-16 h-[2px] bg-blue-500/50 mb-6" />
      <p className="text-gray-400 text-base leading-relaxed font-light mb-8">
        Campaign management, brand positioning, and audience analytics.
      </p>
      
      <div className="flex justify-center w-full mb-8"><img src="/image/marketing.webp" alt="Marketing Workspace" className="max-h-[160px] object-contain opacity-90 drop-shadow-lg" /></div>
    </div>
    
    <div className="mt-auto pt-6 border-t border-white/10">
      <div className="bg-white/5 hover:bg-white/10 text-white px-6 py-4 rounded text-sm font-medium tracking-wide flex justify-between items-center transition-colors">
        <span>Enter Workspace</span>
        <span>→</span>
      </div>
    </div>
  </a>
</div>

          {/* Sign 3: Technical (Left) */}
          <div ref={sign3Ref} className="absolute inset-0 flex items-center justify-start w-full px-8 md:px-32 opacity-0 pointer-events-none">
  <a 
    href="#"
    onClick={(e) => {
      e.preventDefault();
      setTechModalOpen(true);
    }}
    className="max-w-[420px] w-full min-h-[500px] bg-[#111111]/95 backdrop-blur-md border border-white/10 rounded-2xl p-10 shadow-2xl pointer-events-auto cursor-pointer flex flex-col transition-transform duration-300 hover:-translate-y-2 text-left group"
  >
    <div className="flex-1">
      <h3 className="text-4xl font-light text-white mb-4 tracking-wide group-hover:text-blue-400 transition-colors">
        Technical Workspace
      </h3>
      <div className="w-16 h-[2px] bg-blue-500/50 mb-6" />
      <p className="text-gray-400 text-base leading-relaxed font-light mb-8">
        Engineering operations, infrastructure monitoring, and software deployment.
      </p>
      
      <div className="flex justify-center w-full mb-8"><img src="/image/technical.webp" alt="Technical Workspace" className="max-h-[160px] object-contain opacity-90 drop-shadow-lg" /></div>
    </div>
    
    <div className="mt-auto pt-6 border-t border-white/10">
      <div className="bg-white/5 hover:bg-white/10 text-white px-6 py-4 rounded text-sm font-medium tracking-wide flex justify-between items-center transition-colors">
        <span>Enter Workspace</span>
        <span>→</span>
      </div>
    </div>
  </a>
</div>

          {/* Sign 4: Financial (Right) */}
          <div ref={sign4Ref} className="absolute inset-0 flex items-center justify-end w-full px-8 md:px-32 opacity-0 pointer-events-none">
  <a 
    href="#"
    onClick={(e) => {
      e.preventDefault();
      window.dispatchEvent(new CustomEvent("open-department-login", { detail: { departmentName: "Financial", targetUrl: "/financial" } }));
    }}
    className="max-w-[420px] w-full min-h-[500px] bg-[#111111]/95 backdrop-blur-md border border-white/10 rounded-2xl p-10 shadow-2xl pointer-events-auto cursor-pointer flex flex-col transition-transform duration-300 hover:-translate-y-2 text-left group"
  >
    <div className="flex-1">
      <h3 className="text-4xl font-light text-white mb-4 tracking-wide group-hover:text-blue-400 transition-colors">
        Financial Workspace
      </h3>
      <div className="w-16 h-[2px] bg-blue-500/50 mb-6" />
      <p className="text-gray-400 text-base leading-relaxed font-light mb-8">
        Ensuring sustainable growth, managing resources efficiently, and securing long-term economic stability.
      </p>
      
      <div className="flex justify-center w-full mb-8"><img src="/image/financial.webp" alt="Financial Workspace" className="max-h-[160px] object-contain opacity-90 drop-shadow-lg" /></div>
    </div>
    
    <div className="mt-auto pt-6 border-t border-white/10">
      <div className="bg-white/5 hover:bg-white/10 text-white px-6 py-4 rounded text-sm font-medium tracking-wide flex justify-between items-center transition-colors">
        <span>Enter Workspace</span>
        <span>→</span>
      </div>
    </div>
  </a>
</div>
        </div>
      </div>

      {/* Management Modal */}
      {mgmtModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-md animate-in fade-in duration-300">
          <div className="relative w-[90%] max-w-4xl h-[85vh] bg-white rounded-2xl overflow-hidden shadow-2xl flex flex-col">
            <div className="flex justify-between items-center bg-[#8b7082] text-white px-6 py-4">
              <span className="font-bold uppercase tracking-widest text-sm">Management Portal</span>
              <button onClick={() => setMgmtModalOpen(false)} className="text-3xl leading-none">&times;</button>
            </div>
            <div className="flex-1 w-full bg-[#fafafa] overflow-auto p-4">
              <VismeEmbed 
                url="6vz8o9k7-club-membership-sign-up-form" 
                formId="177550" 
                title="Management Portal" 
              />
            </div>
          </div>
        </div>
      )}

      {/* Technical Modal */}
      {techModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-md animate-in fade-in duration-300">
          <div className="relative w-[90%] max-w-4xl h-[85vh] bg-white rounded-2xl overflow-hidden shadow-2xl flex flex-col">
            <div className="flex justify-between items-center bg-[#8b7082] text-white px-6 py-4">
              <span className="font-bold uppercase tracking-widest text-sm">Technical Portal</span>
              <button onClick={() => setTechModalOpen(false)} className="text-3xl leading-none">&times;</button>
            </div>
            <div className="flex-1 w-full bg-[#fafafa] overflow-auto p-4">
              <VismeEmbed 
                url="vm1nwkwd-club-membership-sign-up-form" 
                formId="180145" 
                title="Technical Portal" 
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
